{
    assert(slot == current_slot && size == sizeof last);
    memcpy(&last, data, size); emissions++;
    return refuse ? -1 : 0;
}
static uint64_t tracked_read(uint64_t dst, uint64_t n, uint64_t src,
        uint64_t a, uint64_t b)
